"""Lokaler Server: eine WebSocket-Nachricht trägt Bild und Zustand gemeinsam, REST für Bedienaktionen."""

import asyncio
import logging
from pathlib import Path

from starlette.applications import Starlette
from starlette.requests import Request
from starlette.responses import FileResponse, JSONResponse
from starlette.routing import Mount, Route, WebSocketRoute
from starlette.staticfiles import StaticFiles
from starlette.websockets import WebSocket, WebSocketDisconnect

from .app import App, UserError

log = logging.getLogger(__name__)
WEB = Path(__file__).parent / "web"


def create_server(app: App) -> Starlette:
    async def operator(_: Request):
        return FileResponse(WEB / "operator.html")

    async def stage(_: Request):
        return FileResponse(WEB / "stage.html")

    async def action(request: Request):
        name = request.path_params["name"]
        data = await request.json() if await request.body() else {}
        try:
            await asyncio.to_thread(app.act, name, data)
        except UserError as exc:
            app.message = str(exc)
            return JSONResponse({"ok": False, "message": str(exc)}, status_code=400)
        except TypeError as exc:
            return JSONResponse({"ok": False, "message": f"Ungültige Daten: {exc}"}, status_code=400)
        return JSONResponse({"ok": True})

    async def stream(ws: WebSocket):
        await ws.accept()
        last_seq, idle = -1, 0
        try:
            while True:
                seq, packet = app.packet
                if seq != last_seq and packet:
                    last_seq, idle = seq, 0
                    await ws.send_bytes(packet)
                else:
                    idle += 1
                    # Ohne Kamera kommen keine Frames; Zustand trotzdem regelmäßig schicken.
                    if idle % 25 == 0:
                        app.publish_idle()
                await asyncio.sleep(0.01)
        except (WebSocketDisconnect, RuntimeError):
            pass

    return Starlette(routes=[
        Route("/", operator),
        Route("/stage", stage),
        Route("/api/{name}", action, methods=["POST"]),
        WebSocketRoute("/ws", stream),
        Mount("/web", StaticFiles(directory=WEB)),
    ])
